#!/usr/bin/env bash
# greet build script — uses the `banner` package (a declared dependency)
# at BUILD time, then compiles greet with the banner baked in.
#   $1 = store path of the banner package (interpolated by fix)
#   $2 = output prefix ($FIX_OUT)
set -euo pipefail

banner_bin="$1/bin/banner"
out="$2"
src="$(cd "$(dirname "$0")" && pwd)"

mkdir -p "$out/bin" "$out/share/greet"

# generate the banner with the dependency's binary
"$banner_bin" GREET > "$out/share/greet/banner.txt"

# compile with the FINAL store path baked in ($FIX_ENTRY is where $FIX_OUT
# is atomically installed once the build succeeds — fix computes it before
# building because the store path is deterministic).
cc -O2 -Wall "-DGREET_BANNER_FILE=\"${FIX_ENTRY:?no FIX_ENTRY}/share/greet/banner.txt\"" \
   -o "$out/bin/greet" "$src/greet.c"

printf 'greet: banner generated by %s\n' "$banner_bin" >&2
